from django.db import migrations, models


def clear_email_names(apps, schema_editor):
    """A profile created without a name stored the email as full_name, and
    it was shown as the user's name (web B4). Replace it with first + last,
    or empty."""
    Profile = apps.get_model("users", "Profile")

    for profile in Profile.objects.select_related("user"):
        user = profile.user
        if profile.full_name.strip().lower() == (user.email or "").lower():
            profile.full_name = f"{user.first_name} {user.last_name}".strip()
            profile.save(update_fields=["full_name"])


